/**
 * Функция debounce (дебаунс) — создает обертку вокруг переданной функции,
 * которая будет вызвана только после того, как перестанут приходить вызовы
 * в течение заданного времени ожидания (ms миллисекунд).
 *
 * @param fn - Функция, которую нужно обернуть. Может принимать любые аргументы.
 * @param ms - Время ожидания в миллисекундах.
 * @returns Обернутая функция, которая откладывает выполнение оригинальной функции.
 */
export function debounce<T extends (...a: any[]) => void>(fn: T, ms: number) {
  // Переменная для хранения идентификатора таймера.
  // Тип ReturnType<typeof setTimeout> гарантирует корректный тип для clearTimeout.
  let t: ReturnType<typeof setTimeout> | undefined;

  // Возвращаем новую функцию, которая принимает те же аргументы, что и оригинальная.
  // Parameters<T> извлекает тип аргументов из типа функции T.
  return (...args: Parameters<T>) => {
    // Если таймер уже установлен, отменяем его.
    // Это обеспечивает то, что функция будет вызвана только после последней активации.
    if (t) clearTimeout(t);

    // Устанавливаем новый таймер, который через ms миллисекунд вызовет оригинальную функцию
    // с переданными аргументами.
    t = setTimeout(() => fn(...args), ms);
  };
}
```

