// Мы используем int64, так как atomic.AddInt64 работает именно с int64.
type Counter struct {
    value int64
}

// Метод Inc увеличивает счетчик атомарно.
// atomic.AddInt64 гарантирует, что операция будет выполнена атомарно,
// то есть без гонок данных, даже если несколько горутины вызовут его одновременно.
func (c *Counter) Inc() {
    atomic.AddInt64(&c.value, 1)
}

// Метод Value возвращает текущее значение счетчика.
// atomic.LoadInt64 гарантирует, что мы читаем актуальное значение,
// которое было записано последней атомарной операцией.
func (c *Counter) Value() int64 {
    return atomic.LoadInt64(&c.value)
